// The form already enforced "required" and the number type in the browser. This is the second line: the
// things a browser cannot check, and the things a determined person can POST straight past the form.
//
// It does NOT throw. A human is reading the other end of this, so an invalid order routes to a page that
// says what to fix — an n8n error page with a stack trace is not an answer to "I typed my phone wrong".
const f = $input.first().json;

const text = (v, max) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);

const customer = text(f.customer, 120);
const item = text(f.item, 200);
const note = text(f.note, 500);
const qty = Number(f.qty);

// Vietnamese mobile numbers start with 0, and +84 is the same number written for abroad. Strip everything
// that is not a digit, then normalise the country code back to the local form — otherwise "+84 901 234 567",
// "0901-234-567" and "0901234567" are three different customers in your records.
let phone = String(f.phone ?? '').replace(/[^0-9+]/g, '');
if (phone.startsWith('+84')) phone = '0' + phone.slice(3);
else if (phone.startsWith('84') && phone.length > 9) phone = '0' + phone.slice(2);
phone = phone.replace(/[^0-9]/g, '');

// What to tell them, in the order they are most likely to have got it wrong. One problem at a time: a form
// that lists five faults at once gets abandoned.
let problem = '';
if (!customer) {
  problem = 'Vui long nhap ten. / Please enter your name.';
} else if (!/^0[0-9]{8,10}$/.test(phone)) {
  problem = 'So dien thoai khong hop le — vui long nhap so Viet Nam, vi du 0901234567. / That phone number does not look right — please use a Vietnamese number, e.g. 0901234567.';
} else if (!item) {
  problem = 'Vui long chon mon. / Please choose an item.';
} else if (!Number.isInteger(qty) || qty < 1 || qty > 99) {
  problem = 'So luong phai tu 1 den 99. / Quantity must be between 1 and 99.';
}

// A short, human-quotable reference: the date, so staff can find it, plus four random characters, so two
// orders in the same minute cannot collide. Not a security token - it is read out over the phone.
const now = new Date();
const stamp = now.toISOString().slice(0, 10).replace(/-/g, '');
const suffix = Math.random().toString(36).toUpperCase().slice(2, 6);

return [
  {
    json: {
      valid: problem === '',
      problem,
      ref: `DH-${stamp}-${suffix}`,
      customer,
      phone,
      item,
      qty: Number.isFinite(qty) ? qty : null,
      note,
      receivedAt: now.toISOString(),
      executionId: $execution.id,
    },
  },
];
